-- WA: 120 researched stops.
--
-- 120 new, 0 updating a row already in the index.
-- After running this and scripts/refresh-site.mts, /explore should read
-- 6567.
--
-- Coordinates are deliberately NOT updated on conflict: a checked position
-- must never be replaced by an unchecked one. Where the existing row came
-- from the OpenStreetMap scan and is wrong by a kilometre, delete that slug
-- first and let this insert instead.
--
-- state is deliberately NOT updated either. That is how an overwritten stop
-- in another state keeps its old state and hides — so the collision check
-- above refuses rather than relying on anyone noticing afterwards.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, timezone)
values
  ('International Mermaid Museum', 'international-mermaid-museum', 'museums', 46.91525, -123.9711, 'Aberdeen', 'WA', 'A small coastal museum devoted to mermaid folklore, art, artifacts, and ocean education. Its deliberately narrow focus makes it one of Washington''s strongest true OddWay specialty museums.', 'open', 'https://www.mermaidmuseum.org/', 'America/Los_Angeles'),
  ('Kurt Cobain Memorial Park', 'kurt-cobain-memorial-park', 'weird-history', 46.98423, -123.80541, 'Aberdeen', 'WA', 'A small park beneath the Young Street Bridge memorializes Nirvana frontman Kurt Cobain near places associated with his youth in Aberdeen. Fans leave messages and tributes around the site.', 'open', 'https://www.aberdeenwa.gov/329/Kurt-Cobain-Memorial-Park', 'America/Los_Angeles'),
  ('Lady of the Sea', 'lady-of-the-sea', 'roadside-oddities', 48.5108, -122.60629, 'Anacortes', 'WA', 'This large waterfront figure depicts a woman carrying a ship, blending Anacortes''s maritime identity with oversized public sculpture. It stands outside and can be viewed without entering a building.', 'open', 'https://www.roadsideamerica.com/tip/18737', 'America/Los_Angeles'),
  ('La Merced Ship Hulk', 'la-merced-ship-hulk', 'roadside-oddities', 48.51167, -122.64583, 'Anacortes', 'WA', 'The concrete-and-steel remains of the former schooner La Merced survive as a stationary breakwater at a working waterfront. View only from lawful public areas; the hulk is not an abandoned ship to board or explore.', 'roadside', 'https://npgallery.nps.gov/AssetDetail/NRIS/90001900', 'America/Los_Angeles'),
  ('Outback Kangaroo Farm', 'outback-kangaroo-farm', 'roadside-oddities', 48.22507, -122.09414, 'Arlington', 'WA', 'A rural wildlife attraction centered on kangaroos and wallabies, with other unusual animals appearing in guided encounters. Public access is through scheduled tours rather than unrestricted wandering.', 'limited', 'https://outbackkangaroofarm.com/', 'America/Los_Angeles'),
  ('Recycled Spirits of Iron', 'recycled-spirits-of-iron', 'roadside-oddities', 46.75616, -122.13703, 'Ashford', 'WA', 'Artist Dan Klennert''s property is filled with large sculptures assembled from salvaged machinery, scrap metal, driftwood, and discarded objects. Check current access before making a special trip because it is a private art environment.', 'limited', 'https://www.atlasobscura.com/places/recycled-spirits-of-iron', 'America/Los_Angeles'),
  ('Frog Rock — Bainbridge Island', 'frog-rock-bainbridge-island', 'roadside-oddities', 47.69572, -122.5236, 'Bainbridge Island', 'WA', 'A large roadside boulder has been painted into a wide-eyed frog for decades, creating one of Bainbridge Island''s simplest and most persistent local landmarks. View from a safe lawful roadside position.', 'roadside', 'https://www.atlasobscura.com/places/frog-rock', 'America/Los_Angeles'),
  ('Pia the Peacekeeper', 'pia-the-peacekeeper', 'roadside-oddities', 47.63895, -122.52017, 'Bainbridge Island', 'WA', 'Danish artist Thomas Dambo built this enormous troll from recycled and reclaimed materials near Sakai Park. It is part of the Northwest Trolls project and is reached on foot through public parkland.', 'open', 'https://www.nwtrolls.org/', 'America/Los_Angeles'),
  ('Acid Ball — Waypoint Park', 'acid-ball-waypoint-park', 'roadside-oddities', 48.75074, -122.48556, 'Bellingham', 'WA', 'A 430,000-pound spherical relic from Bellingham''s former pulp mill was preserved and transformed into public art instead of being scrapped. Its industrial history is interpreted inside Waypoint Park.', 'open', 'https://cob.org/services/recreation/parks-trails/parks-guide/waypoint-park', 'America/Los_Angeles'),
  ('Buck Rogers / Flash Gordon Rocket', 'buck-rogers-flash-gordon-rocket', 'roadside-oddities', 48.7514, -122.48166, 'Bellingham', 'WA', 'A retro-futurist rocket assembled from salvaged stop signs, oxygen tanks, lights, and aircraft parts still stands outside the former Rocket Donuts location. The business changed, but the rocket remains the draw.', 'roadside', 'https://www.roadsideamerica.com/tip/40234', 'America/Los_Angeles'),
  ('SPARK Museum of Electrical Invention', 'spark-museum-of-electrical-invention', 'museums', 48.75132, -122.48027, 'Bellingham', 'WA', 'This museum traces electricity and radio through early scientific equipment, telegraphs, radios, and dramatic high-voltage demonstrations. Its giant Tesla-coil-style MegaZapper show gives the collection an appropriately strange edge.', 'open', 'https://www.sparkmuseum.org/', 'America/Los_Angeles'),
  ('Peace Arch', 'peace-arch', 'roadside-oddities', 49.00209, -122.75653, 'Blaine', 'WA', 'A large white arch straddles the U.S.–Canada boundary as a monument to peaceful relations between the countries. The surrounding state park is public, but travelers should still respect all border and customs rules.', 'open', 'https://parks.wa.gov/find-parks/state-parks/peace-arch-historical-state-park', 'America/Los_Angeles'),
  ('Skystone', 'skystone', 'weird-history', 47.15383, -122.19514, 'Bonney Lake', 'WA', 'A large boulder covered with cup-like depressions has long attracted speculation about Indigenous use and meaning. Interpretations vary, so the physical stone is the attraction rather than any single unproven explanation.', 'open', 'https://www.atlasobscura.com/places/skystone', 'America/Los_Angeles'),
  ('USS Turner Joy', 'uss-turner-joy', 'weird-history', 47.56478, -122.62177, 'Bremerton', 'WA', 'A preserved Cold War-era destroyer is permanently moored on Bremerton''s waterfront as a museum ship. Visitors can move through much of the vessel and see the cramped machinery, weapons, and living spaces of a working warship.', 'open', 'https://www.ussturnerjoy.org/', 'America/Los_Angeles'),
  ('Skagit-Squatch', 'skagit-squatch', 'cryptids', 48.47764, -122.32859, 'Burlington', 'WA', 'A towering Sasquatch figure stands beside the highway as a deliberately oversized Pacific Northwest photo stop. It turns the region''s Bigfoot mythology into a concrete routable landmark.', 'roadside', 'https://www.roadsideamerica.com/tip/59530', 'America/Los_Angeles'),
  ('Camlann Medieval Village', 'camlann-medieval-village', 'museums', 47.68882, -121.90531, 'Carnation', 'WA', 'This woodland village recreates life in fourteenth-century England through historic-style buildings, crafts, meals, and costumed interpretation. It operates on scheduled event dates rather than as an always-open theme park.', 'limited', 'http://www.camlann.org/', 'America/Los_Angeles'),
  ('Cashmere Museum & Pioneer Village', 'cashmere-museum-pioneer-village', 'museums', 47.52023, -120.45667, 'Cashmere', 'WA', 'A regional museum and reconstructed pioneer village preserve archaeological material, Indigenous artifacts, historic buildings, and local curiosities. The outdoor village gives the stop more character than a standard display-case museum.', 'limited', 'https://www.cashmeremuseum.org/', 'America/Los_Angeles'),
  ('Shady Lady Bordello Museum', 'shady-lady-bordello-museum', 'weird-history', 46.71769, -122.95334, 'Centralia', 'WA', 'A tiny museum interprets Centralia''s vice-district and bordello history through period objects and local stories. Hours can be irregular, so this is a check-ahead stop rather than a guaranteed walk-in attraction.', 'limited', 'https://www.visitcentraliachehalis.com/', 'America/Los_Angeles'),
  ('Codger Pole', 'codger-pole', 'roadside-oddities', 46.87829, -117.36533, 'Colfax', 'WA', 'A 65-foot carved pole commemorates a rematch between elderly alumni of rival high-school football teams. The figures stacked along it make the monument look like a deliberately eccentric cousin of a traditional carved pole.', 'open', 'https://www.atlasobscura.com/places/codger-pole', 'America/Los_Angeles'),
  ('Bob the Talking Bear', 'bob-the-talking-bear', 'roadside-oddities', 48.53917, -121.7449, 'Concrete', 'WA', 'Concrete''s carved wooden bear mascot talks when visitors press a button, delivering a short recorded introduction to town. The sculpture dates to 1980 and remains an active local roadside attraction.', 'open', 'https://www.roadsideamerica.com/tip/93282', 'America/Los_Angeles'),
  ('Drive Under Concrete High School', 'drive-under-concrete-high-school', 'roadside-oddities', 48.532, -121.75881, 'Concrete', 'WA', 'A public road passes directly beneath part of Concrete High School, creating the unusual experience of literally driving under a school building. Stay on the road and do not treat the school grounds as a tourist facility.', 'roadside', 'https://www.roadsideamerica.com/tip/11851', 'America/Los_Angeles'),
  ('Silo Park', 'silo-park', 'weird-history', 48.53658, -121.75811, 'Concrete', 'WA', 'Massive former cement silos were repainted with a giant ''WELCOME TO CONCRETE'' message and preserved as the defining landmark of town. The surrounding public park provides the lawful viewing point.', 'open', 'https://www.cascadeloop.com/account/silo-park', 'America/Los_Angeles'),
  ('Copalis State Airport', 'copalis-state-airport', 'roadside-oddities', 47.14486, -124.18925, 'Copalis Beach', 'WA', 'Washington''s Copalis State Airport is a designated stretch of Pacific beach where aircraft can land on the sand when conditions allow. Tide, weather, aviation rules, and beach users make this an access-dependent stop rather than a normal runway visit.', 'limited', 'https://wsdot.wa.gov/travel/aviation/airports-list/copalis-state', 'America/Los_Angeles'),
  ('Ape Cave', 'ape-cave', 'roadside-oddities', 46.1083, -122.2114, 'Cougar', 'WA', 'A long lava tube created by ancient Mount St. Helens eruptions lets visitors walk underground through volcanic rock rather than limestone. Seasonal road conditions, cave conditions, and current reservation rules should be checked before visiting.', 'limited', 'https://www.wta.org/go-hiking/hikes/ape-cave', 'America/Los_Angeles'),
  ('Dry Falls Visitor Center', 'dry-falls-visitor-center', 'roadside-oddities', 47.60648, -119.3647, 'Coulee City', 'WA', 'A colossal dry cliff marks the site of Ice Age flood waterfalls that once dwarfed modern Niagara Falls. The visitor center overlooks the enormous abandoned cataract and explains the catastrophic floods that carved the landscape.', 'open', 'https://parks.wa.gov/find-parks/state-parks/sun-lakes-dry-falls-state-park', 'America/Los_Angeles'),
  ('Grand Coulee Dam Visitor Center', 'grand-coulee-dam-visitor-center', 'roadside-oddities', 47.96001, -118.98676, 'Coulee Dam', 'WA', 'One of North America''s largest concrete structures spans the Columbia River here, creating an almost absurdly large piece of human engineering. The visitor center interprets the dam, hydroelectric system, and regional impacts.', 'open', 'https://www.usbr.gov/pn/grandcoulee/visit/', 'America/Los_Angeles'),
  ('Price Sculpture Forest', 'price-sculpture-forest', 'roadside-oddities', 48.22106, -122.65276, 'Coupeville', 'WA', 'A wooded trail winds through a collection of contemporary sculptures placed among trees and ferns. The unusual forest-gallery setting makes the art feel discovered rather than displayed in a conventional museum.', 'open', 'https://sculptureforest.org/', 'America/Los_Angeles'),
  ('Maury Island UFO Incident Mural', 'maury-island-ufo-incident-mural', 'ufos', 47.42183, -122.46074, 'Vashon', 'WA', 'A public mural commemorates the controversial 1947 Maury Island UFO story, often discussed as one of the earliest modern flying-saucer cases. The art gives travelers a concrete stop tied to a story otherwise spread across the island.', 'open', 'https://www.seattlesouthside.com/directory/maury-island-incident-mural/', 'America/Los_Angeles'),
  ('Gehrke Windmill Garden', 'gehrke-windmill-garden', 'roadside-oddities', 47.93692, -119.01581, 'Grand Coulee', 'WA', 'Dozens of homemade windmills and whirligigs created by Emil Gehrke fill a yard with spinning figures and mechanical folk art. View respectfully from lawful public areas unless current access is explicitly offered.', 'roadside', 'https://www.atlasobscura.com/places/gehrke-windmill-garden', 'America/Los_Angeles'),
  ('Dick and Jane''s Spot', 'dick-and-janes-spot', 'roadside-oddities', 46.99261, -120.54752, 'Ellensburg', 'WA', 'The exterior of a private home and yard is covered with bottle caps, reflectors, found objects, mosaics, and kinetic pieces created over decades. It is meant to be viewed from the public sidewalk, not entered as a museum.', 'roadside', 'https://www.atlasobscura.com/places/dick-and-janes-spot', 'America/Los_Angeles'),
  ('Satsop Cooling Towers', 'satsop-cooling-towers', 'weird-history', 46.96004, -123.47413, 'Elma', 'WA', 'Two enormous cooling towers survive from the unfinished Satsop nuclear power project, creating one of Washington''s most surreal industrial landscapes. The surrounding site is an active business park, so obey all barriers and access rules.', 'roadside', 'https://www.satsop.com/', 'America/Los_Angeles'),
  ('Earthquake Point', 'earthquake-point', 'weird-history', 47.70846, -120.21702, 'Entiat', 'WA', 'A roadside marker identifies the area where an 1872 earthquake sent a huge mass of rock into the Columbia River. The stop ties a quiet modern highway to one of the Pacific Northwest''s largest known historic earthquakes.', 'roadside', 'https://www.hmdb.org/', 'America/Los_Angeles'),
  ('Flying Heritage & Combat Armor Museum', 'flying-heritage-combat-armor-museum', 'roadside-oddities', 47.89948, -122.28008, 'Everett', 'WA', 'Restored military aircraft, tanks, and armored vehicles fill this unusually machinery-heavy museum. Many objects are presented as functioning engineering artifacts rather than static replicas.', 'open', 'https://flyingheritage.org/', 'America/Los_Angeles'),
  ('Rucker Pyramid Tomb', 'rucker-pyramid-tomb', 'weird-history', 47.96292, -122.2031, 'Everett', 'WA', 'A large stone pyramid marks the Rucker family plot in Evergreen Cemetery, looking dramatically different from the surrounding headstones. Visit only during cemetery hours and treat the site as a grave, not a climbing structure.', 'limited', 'https://www.atlasobscura.com/places/rucker-pyramid', 'America/Los_Angeles'),
  ('Forks Timber Museum', 'forks-timber-museum', 'museums', 47.93659, -124.39408, 'Forks', 'WA', 'Logging equipment, pioneer artifacts, and a reconstructed fire lookout interpret the timber history of the Olympic Peninsula. The giant logging imagery and remote setting give it a strong roadside-history character.', 'limited', 'https://www.forkstimbermuseum.org/', 'America/Los_Angeles'),
  ('John''s Beachcombing Museum', 'johns-beachcombing-museum', 'museums', 47.96252, -124.40136, 'Forks', 'WA', 'A private collection turns decades of beachcombing into displays of glass floats, drift material, marine debris, messages, and strange objects that washed ashore. Check current hours before making the drive.', 'limited', 'https://johnsbeachcombingmuseum.com/', 'America/Los_Angeles'),
  ('American Camp — San Juan Island NHP', 'american-camp-san-juan-island-nhp', 'weird-history', 48.4648, -123.02435, 'Friday Harbor', 'WA', 'This landscape preserves the U.S. side of the 1859 ''Pig War,'' an international crisis triggered after an American settler shot a British-owned pig. Trails and interpretation explain how an absurd animal dispute nearly became a military conflict.', 'open', 'https://www.nps.gov/sajh/learn/historyculture/the-pig-war.htm', 'America/Los_Angeles'),
  ('English Camp — San Juan Island NHP', 'english-camp-san-juan-island-nhp', 'weird-history', 48.58649, -123.14908, 'Friday Harbor', 'WA', 'The British encampment from the Pig War survives with historic structures and landscaped grounds on the opposite side of San Juan Island. Together with American Camp, it preserves one of the strangest near-wars in U.S. history.', 'open', 'https://www.nps.gov/sajh/learn/historyculture/the-pig-war.htm', 'America/Los_Angeles'),
  ('Afterglow Vista', 'afterglow-vista', 'weird-history', 48.61595, -123.149, 'Roche Harbor', 'WA', 'A circular stone mausoleum surrounds the graves of John S. McMillin and family beneath a deliberately symbolic open-air rotunda. The site lies within a cemetery and should be visited quietly during lawful access.', 'limited', 'https://www.rocheharbor.com/', 'America/Los_Angeles'),
  ('The Whale Museum', 'the-whale-museum', 'museums', 48.53576, -123.01719, 'Friday Harbor', 'WA', 'This museum is devoted to whales of the Salish Sea, especially the region''s endangered Southern Resident killer whales. Skeletons, research material, recordings, and natural-history exhibits make it more specialized than a general aquarium stop.', 'open', 'https://whalemuseum.org/', 'America/Los_Angeles'),
  ('Hisey Dinosaur Park', 'hisey-dinosaur-park', 'roadside-oddities', 46.33987, -120.19557, 'Granger', 'WA', 'Granger has embraced prehistoric roadside kitsch with dinosaur sculptures spread through town, including a concentrated group at Hisey Park. The project grew from the area''s connection to nearby fossil discoveries.', 'open', 'https://www.cityofgranger.com/', 'America/Los_Angeles'),
  ('Manhattan Project NHP — Hanford Visitor Center', 'manhattan-project-nhp-hanford-visitor-center', 'weird-history', 46.31856, -119.30042, 'Richland', 'WA', 'The visitor center interprets Hanford''s role in producing plutonium for the Manhattan Project and the enormous secret industrial landscape that followed. Some associated reactor tours are subject to separate closures and reservations.', 'open', 'https://www.nps.gov/mapr/planyourvisit/hanford.htm', 'America/Los_Angeles'),
  ('LIGO Exploration Center', 'ligo-exploration-center', 'roadside-oddities', 46.45514, -119.40765, 'Richland', 'WA', 'The public center at the Hanford gravitational-wave observatory explains how kilometer-scale laser interferometers detect ripples in spacetime. Its location beside a working world-class physics instrument gives the stop unusual scientific scale.', 'limited', 'https://www.ligo.caltech.edu/WA/page/lexc', 'America/Los_Angeles'),
  ('REACH Museum', 'reach-museum', 'museums', 46.23616, -119.21673, 'Richland', 'WA', 'Exhibits connect Ice Age floods, Columbia River ecology, Indigenous history, and the Hanford nuclear story. The combination of geology and atomic history makes it a useful context stop for several stranger destinations nearby.', 'open', 'https://visitthereach.us/', 'America/Los_Angeles'),
  ('USS Triton Sail Park', 'uss-triton-sail-park', 'weird-history', 46.34745, -119.26925, 'Richland', 'WA', 'The preserved sail and conning-tower structure from the nuclear submarine USS Triton stands beside the Columbia River. It memorializes a vessel famous for completing the first submerged circumnavigation of the globe.', 'open', 'https://portofbenton.com/community/uss-triton-sail-park/', 'America/Los_Angeles'),
  ('Coyote Canyon Mammoth Site', 'coyote-canyon-mammoth-site', 'museums', 46.1587, -119.2648, 'Kennewick', 'WA', 'An active excavation preserves the remains of a Columbian mammoth discovered in the hills above the Tri-Cities. Public access is through scheduled tours or events, not independent entry onto the research site.', 'limited', 'https://www.mcbones.org/', 'America/Los_Angeles'),
  ('Friendly Bigfoot — Espresso Chalet', 'friendly-bigfoot-espresso-chalet', 'cryptids', 47.80866, -121.56208, 'Index', 'WA', 'A large Sasquatch figure stands beside the highway outside the Espresso Chalet, a long-running Bigfoot-themed photo stop on Stevens Pass. It converts Cascades cryptid lore into an easy, legal roadside visit.', 'roadside', 'https://www.roadsideamerica.com/tip/10490', 'America/Los_Angeles'),
  ('Jakob Two Trees', 'jakob-two-trees', 'roadside-oddities', 47.52423, -122.03249, 'Issaquah', 'WA', 'Thomas Dambo''s giant recycled-wood troll hides along a public trail near downtown Issaquah. The sculpture combines Pacific Northwest forest imagery with Scandinavian troll folklore.', 'open', 'https://www.nwtrolls.org/', 'America/Los_Angeles'),
  ('U.S. Naval Undersea Museum', 'us-naval-undersea-museum', 'museums', 47.69927, -122.62487, 'Keyport', 'WA', 'Submarines, torpedoes, diving equipment, and deep-ocean technology fill the U.S. Navy''s official undersea museum. The collection includes full-size machines that make underwater warfare and research unusually tangible.', 'open', 'https://navalunderseamuseum.org/', 'America/Los_Angeles'),
  ('Leavenworth Nutcracker Museum', 'leavenworth-nutcracker-museum', 'museums', 47.59472, -120.6625, 'Leavenworth', 'WA', 'Thousands of nutcrackers from many periods and cultures fill a museum dedicated almost entirely to one type of object. The collection ranges from practical tools to elaborate carved figures and novelty designs.', 'open', 'https://nutcrackermuseum.com/', 'America/Los_Angeles'),
  ('Mima Mounds Natural Area Preserve', 'mima-mounds-natural-area-preserve', 'roadside-oddities', 46.90457, -123.04863, 'Littlerock', 'WA', 'Thousands of evenly spaced earthen mounds cover this protected prairie, creating a landscape whose origin has inspired competing geological and biological explanations. Stay on designated public trails to protect the fragile habitat.', 'open', 'https://www.dnr.wa.gov/MimaMounds', 'America/Los_Angeles'),
  ('Marsh''s Free Museum', 'marshs-free-museum', 'museums', 46.34927, -124.05504, 'Long Beach', 'WA', 'This classic roadside museum-shop mixes shells, taxidermy, arcade machines, curiosities, and the famous preserved ''Jake the Alligator Man.'' It is one of Washington''s strongest old-school cabinet-of-curiosities stops.', 'open', 'https://marshsfreemuseum.com/', 'America/Los_Angeles'),
  ('World Kite Museum', 'world-kite-museum', 'museums', 46.34556, -124.05804, 'Long Beach', 'WA', 'A museum devoted to kites documents their art, engineering, military uses, and cultural history. Long Beach''s windy coast makes the narrow specialty feel especially tied to place.', 'open', 'https://www.worldkitemuseum.com/', 'America/Los_Angeles'),
  ('Nutty Narrows Bridge', 'nutty-narrows-bridge', 'roadside-oddities', 46.14147, -122.94049, 'Longview', 'WA', 'Longview''s famous squirrel bridge was created so squirrels could cross a busy street above traffic. The original spawned additional squirrel bridges and an unusually serious civic tradition around tiny wildlife infrastructure.', 'open', 'https://www.atlasobscura.com/places/nutty-narrows-bridge', 'America/Los_Angeles'),
  ('Maryhill Stonehenge Memorial', 'maryhill-stonehenge-memorial', 'roadside-oddities', 45.69464, -120.80565, 'Maryhill', 'WA', 'A full-scale concrete Stonehenge replica overlooks the Columbia River, built by Sam Hill as a World War I memorial. The monument was based on an outdated interpretation of Stonehenge as a place of human sacrifice, adding another layer of strangeness.', 'open', 'https://www.maryhillmuseum.org/outside/stonehenge-memorial', 'America/Los_Angeles'),
  ('Maryhill Museum of Art', 'maryhill-museum-of-art', 'museums', 45.6775, -120.8648, 'Goldendale', 'WA', 'A grand mansion-turned-museum in a remote Columbia Gorge setting holds an eclectic mix of art, chess sets, Indigenous material, and objects associated with Queen Marie of Romania. Its collection is as unexpected as its location.', 'open', 'https://www.maryhillmuseum.org/', 'America/Los_Angeles'),
  ('Samuel Hill Crypt', 'samuel-hill-crypt', 'weird-history', 45.6936, -120.80659, 'Maryhill', 'WA', 'Road-builder and Maryhill founder Samuel Hill is buried beneath a stark concrete monument near his Stonehenge memorial. The grave is a memorial site, so visit respectfully and do not climb on the structure.', 'limited', 'https://www.maryhillmuseum.org/', 'America/Los_Angeles'),
  ('Ginkgo Petrified Forest Interpretive Center', 'ginkgo-petrified-forest-interpretive-center', 'museums', 46.94551, -120.01295, 'Vantage', 'WA', 'One of the world''s unusually diverse petrified-wood deposits is preserved above the Columbia River. Exhibits and nearby trails reveal fossilized trees from ancient forests buried by volcanic activity.', 'open', 'https://parks.wa.gov/find-parks/state-parks/ginkgo-petrified-forest-state-park', 'America/Los_Angeles'),
  ('Wild Horses Monument — Grandfather Cuts Loose the Ponies', 'wild-horses-monument-grandfather-cuts-loose-the-ponies', 'roadside-oddities', 46.9646, -119.9643, 'Vantage', 'WA', 'A line of metal horses appears to gallop along a ridge above the Columbia River. The official trailhead requires a steep, exposed hike to reach the sculpture, so weather and footing matter.', 'limited', 'https://www.wta.org/go-hiking/hikes/wild-horses-monument', 'America/Los_Angeles'),
  ('Boeing Future of Flight', 'boeing-future-of-flight', 'roadside-oddities', 47.92125, -122.29007, 'Mukilteo', 'WA', 'The visitor center interprets commercial aircraft design and assembly beside Boeing''s enormous Everett factory complex. Factory experiences are ticketed and operational access can change, so check current offerings.', 'limited', 'https://www.boeingfutureofflight.com/', 'America/Los_Angeles'),
  ('Twede''s Cafe — Twin Peaks Double R Diner', 'twedes-cafe-twin-peaks-double-r-diner', 'weird-history', 47.49517, -121.78685, 'North Bend', 'WA', 'The diner used as the Double R in ''Twin Peaks'' remains an operating restaurant and embraces its connection to the series. It is one of the most recognizable real-world locations in the show''s fictional geography.', 'open', 'https://twedescafe.com/', 'America/Los_Angeles'),
  ('Snoqualmie Falls — Twin Peaks Opening Location', 'snoqualmie-falls-twin-peaks-opening-location', 'weird-history', 47.54172, -121.83768, 'Snoqualmie', 'WA', 'The 268-foot waterfall appears prominently in the opening imagery of ''Twin Peaks'' and towers beside the real-life Salish Lodge. Public viewpoints make it a straightforward film-location stop as well as a geological landmark.', 'open', 'https://www.snoqualmiefalls.com/', 'America/Los_Angeles'),
  ('DirtFish Rally School — Twin Peaks Sheriff''s Station', 'dirtfish-rally-school-twin-peaks-sheriffs-station', 'weird-history', 47.53763, -121.81151, 'Snoqualmie', 'WA', 'The former Weyerhaeuser mill property contains the building used as the Twin Peaks Sheriff''s Department and Packard Sawmill setting. It is now an active rally school, so visitors should respect business operations and posted access.', 'limited', 'https://drive.dirtfish.com/', 'America/Los_Angeles'),
  ('Ronette''s Bridge', 'ronettes-bridge', 'weird-history', 47.52988, -121.80683, 'Snoqualmie', 'WA', 'This former railroad bridge, now part of a public trail, was used for the unsettling scene in which Ronette Pulaski emerges after her ordeal in ''Twin Peaks.'' The modern trail setting is far calmer than its screen appearance.', 'open', 'https://www.discovernorthbend.com/195/Twin-Peaks-Filming-Locations', 'America/Los_Angeles'),
  ('Fall City Roadhouse — Twin Peaks Roadhouse', 'fall-city-roadhouse-twin-peaks-roadhouse', 'weird-history', 47.56727, -121.88839, 'Fall City', 'WA', 'The historic roadhouse exterior appeared as a key nightlife location in the ''Twin Peaks'' universe. It remains a real operating business, so it can be visited without treating the site like an abandoned set.', 'open', 'https://www.discovernorthbend.com/195/Twin-Peaks-Filming-Locations', 'America/Los_Angeles'),
  ('Mt Si Motel — Twin Peaks Red Diamond Motel', 'mt-si-motel-twin-peaks-red-diamond-motel', 'weird-history', 47.48386, -121.76297, 'North Bend', 'WA', 'This roadside motel supplied the exterior used for the Red Diamond Motel in ''Twin Peaks: Fire Walk with Me.'' Treat it as an operating/private lodging property and view the exterior from lawful public areas unless staying there.', 'roadside', 'https://www.discovernorthbend.com/195/Twin-Peaks-Filming-Locations', 'America/Los_Angeles'),
  ('Bigfoot Family', 'bigfoot-family', 'cryptids', 45.6385, -121.9742, 'North Bonneville', 'WA', 'A family of carved Sasquatches occupies the city''s Discovery Trail network, with more Bigfoot figures scattered around town. The municipal trail plan explicitly incorporates the carvings into the public route.', 'open', 'https://northbonneville.net/wp-content/uploads/2019-Bonneville-Discovery-Trails-Plan.pdf', 'America/Los_Angeles'),
  ('Sharky''s Shark Head Entrance', 'sharkys-shark-head-entrance', 'roadside-oddities', 46.97465, -124.15857, 'Ocean Shores', 'WA', 'Visitors enter this coastal gift shop through the open mouth of an enormous shark facade. The deliberately theatrical storefront is one of Ocean Shores'' most recognizable roadside oddities.', 'open', 'https://www.sharkysos.net/', 'America/Los_Angeles'),
  ('Seatco Prison Site Marker', 'seatco-prison-site-marker', 'weird-history', 46.79306, -122.86972, 'Bucoda', 'WA', 'A marker recalls Washington Territory''s first penitentiary, once located at Seatco before Bucoda took its current name. The original prison is gone, making the marker the lawful route point for the story.', 'open', 'https://www.co.thurston.wa.us/history/docs/markers/Seatco-Prison-Site.pdf', 'America/Los_Angeles'),
  ('Apollo 14 Moon Tree', 'apollo-14-moon-tree', 'weird-history', 47.03575, -122.90113, 'Olympia', 'WA', 'A Douglas-fir grown from seed carried around the Moon aboard Apollo 14 stands on the Washington State Capitol campus. The ordinary-looking tree has one of the strangest travel histories of any plant in the state.', 'open', 'https://capitol.wa.gov/discover/trees/moon-trees', 'America/Los_Angeles'),
  ('Olympic Flight Museum', 'olympic-flight-museum', 'museums', 46.97589, -122.89779, 'Tumwater', 'WA', 'Historic aircraft, helicopters, and military aviation artifacts fill a working-airfield museum south of Olympia. The collection''s full-size machines make it a strong mechanical-history stop.', 'open', 'https://www.olympicflightmuseum.com/', 'America/Los_Angeles'),
  ('WSU Bear Center', 'wsu-bear-center', 'roadside-oddities', 46.72948, -117.13925, 'Pullman', 'WA', 'Washington State University''s research center keeps grizzly bears for long-term studies of nutrition, hibernation, and physiology. There are no conventional zoo-style formal tours; public viewing opportunities depend on current seasonal conditions and center rules.', 'limited', 'https://bearcenter.wsu.edu/visit/', 'America/Los_Angeles'),
  ('Northwest Carriage Museum', 'northwest-carriage-museum', 'museums', 46.68357, -123.73283, 'Raymond', 'WA', 'A large collection of restored horse-drawn vehicles includes elegant carriages, wagons, sleighs, and working-era equipment. The narrow transportation focus makes the museum unusually immersive.', 'open', 'https://nwcarriagemuseum.org/', 'America/Los_Angeles'),
  ('Raymond Metal People', 'raymond-metal-people', 'roadside-oddities', 46.68645, -123.7319, 'Raymond', 'WA', 'More than 200 metal silhouettes of people and animals appear along streets, docks, and roads around Raymond. The town-scale installation turns an ordinary drive into a long scavenger hunt for welded figures.', 'open', 'https://www.weyerhaeuser.com/blog/see-raymond-washingtons-metal-people/', 'America/Los_Angeles'),
  ('Willapa Seaport Museum', 'willapa-seaport-museum', 'museums', 46.68372, -123.73292, 'Raymond', 'WA', 'This compact museum preserves maritime and logging history from Willapa Harbor through ship models, tools, photographs, and local artifacts. Check current opening hours before routing a trip around it.', 'limited', 'https://www.visitwillapaharbor.com/', 'America/Los_Angeles'),
  ('Jimi Hendrix Memorial', 'jimi-hendrix-memorial', 'weird-history', 47.4865, -122.174, 'Renton', 'WA', 'An elaborate granite memorial marks the grave of guitarist Jimi Hendrix at Greenwood Memorial Park. It functions as both a cemetery monument and a pilgrimage site for music fans, so cemetery etiquette applies.', 'limited', 'https://www.greenwoodmempark.com/', 'America/Los_Angeles'),
  ('Roslyn Cafe Camel Mural', 'roslyn-cafe-camel-mural', 'weird-history', 47.2227, -120.9939, 'Roslyn', 'WA', 'The camel mural on the Roslyn Cafe building appeared in the opening credits of ''Northern Exposure,'' where Roslyn stood in for fictional Cicely, Alaska. The mural remains visible even as the cafe''s operating status and hours change.', 'open', 'https://explorewashingtonstate.com/roslyn/', 'America/Los_Angeles'),
  ('Fremont Troll', 'fremont-troll', 'roadside-oddities', 47.6511, -122.34732, 'Seattle', 'WA', 'An enormous concrete troll grips a real Volkswagen Beetle beneath the Aurora Bridge. Created in 1990, it has become one of Seattle''s defining pieces of deliberately strange public art.', 'open', 'https://fremont.com/about/fremont-troll/', 'America/Los_Angeles'),
  ('Lenin Statue', 'lenin-statue', 'roadside-oddities', 47.65147, -122.3513, 'Seattle', 'WA', 'A large bronze statue of Vladimir Lenin, originally made for Czechoslovakia, stands privately owned in the middle of Fremont. Its relocation from the former Eastern Bloc to a Seattle shopping district makes the setting intentionally jarring.', 'open', 'https://fremont.com/about/lenin/', 'America/Los_Angeles'),
  ('Fremont Rocket', 'fremont-rocket', 'roadside-oddities', 47.65056, -122.35107, 'Seattle', 'WA', 'A Cold War-era aircraft tail section was transformed into a retro rocket and mounted above Fremont. The absurd reuse fits the neighborhood''s long-running ''Center of the Universe'' identity.', 'open', 'https://fremont.com/rocket/', 'America/Los_Angeles'),
  ('Waiting for the Interurban', 'waiting-for-the-interurban', 'roadside-oddities', 47.64947, -122.34946, 'Seattle', 'WA', 'A group of cast-aluminum people and a dog eternally wait for a streetcar that no longer comes. Locals regularly dress and decorate the figures, making the artwork change with events and jokes.', 'open', 'https://fremont.com/about/waiting-for-the-interurban/', 'America/Los_Angeles'),
  ('Center of the Universe Guidepost', 'center-of-the-universe-guidepost', 'roadside-oddities', 47.6504, -122.35021, 'Seattle', 'WA', 'A colorful signpost in Fremont points toward destinations real, fictional, nearby, and impossibly distant. It formalizes the neighborhood''s tongue-in-cheek claim to be the Center of the Universe.', 'open', 'https://fremont.com/about/centeruniverseguidepost/', 'America/Los_Angeles'),
  ('Gum Wall', 'gum-wall', 'roadside-oddities', 47.60842, -122.34038, 'Seattle', 'WA', 'Layers of chewed gum cover brick walls beneath Pike Place Market, turning a once-unwanted habit into a constantly renewed participatory landmark. The wall has been cleaned before, only to refill.', 'open', 'https://www.pikeplacemarket.org/vendor/the-gum-wall/', 'America/Los_Angeles'),
  ('Hat ''n'' Boots — Oxbow Park', 'hat-n-boots-oxbow-park', 'roadside-oddities', 47.545, -122.3217, 'Seattle', 'WA', 'A giant cowboy hat and pair of boots survive from a 1950s Western-themed gas station. The rescued fiberglass structures now stand in a public park as monuments to novelty roadside architecture.', 'open', 'https://www.seattle.gov/parks/allparks/oxbow-park', 'America/Los_Angeles'),
  ('Ye Olde Curiosity Shop', 'ye-olde-curiosity-shop', 'museums', 47.60432, -122.34003, 'Seattle', 'WA', 'This century-old waterfront shop mixes souvenirs with long-running displays of shrunken-head lore, mummies, taxidermy, odd artifacts, and sideshow-style curiosities. It is a surviving example of the old tourist curiosity-shop tradition.', 'open', 'https://www.yeoldecuriosityshop.com/', 'America/Los_Angeles'),
  ('Seattle Pinball Museum', 'seattle-pinball-museum', 'museums', 47.59802, -122.32487, 'Seattle', 'WA', 'Rows of playable pinball machines trace the evolution of the game across decades. Rather than viewing the collection behind glass, admission is built around actually using the machines.', 'open', 'https://www.seattlepinballmuseum.com/', 'America/Los_Angeles'),
  ('Beneath the Streets — Seattle Underground', 'beneath-the-streets-seattle-underground', 'weird-history', 47.60216, -122.33435, 'Seattle', 'WA', 'Guided tours enter surviving passageways beneath Pioneer Square, remnants of street-level changes after the Great Seattle Fire. Access is scheduled and controlled rather than an invitation to explore utility spaces independently.', 'limited', 'https://www.beneath-the-streets.com/', 'America/Los_Angeles'),
  ('A Sound Garden', 'a-sound-garden', 'roadside-oddities', 47.68546, -122.24985, 'Seattle', 'WA', 'Wind moving through tall steel towers creates changing tones at this outdoor sound sculpture on the NOAA campus. Visitors must follow current federal-campus check-in and access procedures.', 'limited', 'https://www.seattle.gov/parks/allparks/magnuson-park/partner-organizations', 'America/Los_Angeles'),
  ('Bruce and Brandon Lee Graves', 'bruce-and-brandon-lee-graves', 'weird-history', 47.63375, -122.31587, 'Seattle', 'WA', 'Martial-arts icon Bruce Lee and his son Brandon Lee are buried side by side at Lake View Cemetery. The graves draw visitors from around the world, but remain an active family memorial within a cemetery.', 'limited', 'https://lakeviewcemeteryassociation.com/', 'America/Los_Angeles'),
  ('Archie McPhee & Rubber Chicken Museum', 'archie-mcphee-rubber-chicken-museum', 'museums', 47.66152, -122.34169, 'Seattle', 'WA', 'A novelty store full of bizarre toys, masks, rubber animals, and gag objects contains its own tongue-in-cheek Rubber Chicken Museum. It is essentially a functioning shop built around curated absurdity.', 'open', 'https://archiemcpheeseattle.com/', 'America/Los_Angeles'),
  ('Georgetown Steam Plant', 'georgetown-steam-plant', 'weird-history', 47.54282, -122.31667, 'Seattle', 'WA', 'A monumental early-twentieth-century power plant preserves huge turbines, generators, and an interior that feels closer to a machine cathedral than a utility building. Public access is generally through scheduled open houses or tours.', 'limited', 'https://www.seattle.gov/city-light/in-the-community/tours-recreation-and-education/georgetown-steam-plant', 'America/Los_Angeles'),
  ('Hiram M. Chittenden Locks Fish Ladder', 'hiram-m-chittenden-locks-fish-ladder', 'roadside-oddities', 47.66565, -122.39652, 'Seattle', 'WA', 'The Ballard Locks combine working ship locks with a fish ladder where migrating salmon can be viewed through underwater windows. It is a rare place where major engineering and animal migration are visible in the same stop.', 'open', 'https://www.nws.usace.army.mil/Missions/Civil-Works/Locks-and-Dams/Chittenden-Locks/', 'America/Los_Angeles'),
  ('Frankie Feetsplinter', 'frankie-feetsplinter', 'roadside-oddities', 47.66851, -122.39261, 'Seattle', 'WA', 'A giant troll built from reclaimed wood crouches near the National Nordic Museum and Burke-Gilman Trail in Ballard. It is one of Thomas Dambo''s Northwest Trolls.', 'open', 'https://www.nwtrolls.org/', 'America/Los_Angeles'),
  ('Bruun Idun', 'bruun-idun', 'roadside-oddities', 47.5311, -122.4005, 'Seattle', 'WA', 'Thomas Dambo''s flute-playing troll hides among the trees near the shoreline in Lincoln Park. Finding the sculpture is intentionally part of the experience, and the park is open during posted hours.', 'open', 'https://www.nwtrolls.org/', 'America/Los_Angeles'),
  ('Northern State Recreation Area', 'northern-state-recreation-area', 'weird-history', 48.5334, -122.193, 'Sedro-Woolley', 'WA', 'Public trails cross portions of the former Northern State Hospital farm landscape, where agricultural and institutional remnants survive among fields and woods. Historic structures should be observed from permitted areas rather than entered.', 'open', 'https://www.skagitcountywa.gov/Departments/ParksAndRecreation/parks/nsra.htm', 'America/Los_Angeles'),
  ('Sequim Museum & Arts — Manis Mastodon Exhibit', 'sequim-museum-arts-manis-mastodon-exhibit', 'museums', 48.08396, -123.10156, 'Sequim', 'WA', 'The museum displays actual bones and tusks from the Manis Mastodon, a roughly 13,800-year-old discovery important to the study of early human activity in North America. It provides a legitimate public alternative to visiting the protected archaeological site itself.', 'limited', 'https://www.sequimmuseum.com/', 'America/Los_Angeles'),
  ('Mount St. Helens Visitor Center', 'mount-st-helens-visitor-center', 'weird-history', 46.29458, -122.82194, 'Silver Lake', 'WA', 'Exhibits, films, and landscape views explain the 1980 eruption of Mount St. Helens and the massive destruction it caused. It is the best all-season orientation point for the volcano''s stranger and more remote sites.', 'open', 'https://parks.wa.gov/find-parks/state-parks/mount-st-helens-visitor-center', 'America/Los_Angeles'),
  ('Ape Canyon Trailhead', 'ape-canyon-trailhead', 'cryptids', 46.16553, -122.09105, 'Cougar', 'WA', 'The trail carries the name of a 1924 story in which miners claimed that ape-like creatures attacked their cabin near Mount St. Helens. Today it is a legitimate trailhead, but seasonal snow and Forest Road closures can prevent vehicle access.', 'limited', 'https://www.visitmtsthelens.com/business-directory/ape-canyon-trail-234/', 'America/Los_Angeles'),
  ('Bob''s Java Jive', 'bobs-java-jive', 'roadside-oddities', 47.23172, -122.46448, 'Tacoma', 'WA', 'A giant coffee-pot-shaped building has served as a Tacoma tavern and music venue for decades. Its exaggerated novelty architecture survives as one of the city''s classic roadside landmarks.', 'limited', 'https://www.roadsideamerica.com/story/2233', 'America/Los_Angeles'),
  ('Chihuly Bridge of Glass', 'chihuly-bridge-of-glass', 'roadside-oddities', 47.24559, -122.4353, 'Tacoma', 'WA', 'A pedestrian bridge is packed with large-scale Dale Chihuly glass installations, including a ceiling of hundreds of colorful forms. It functions simultaneously as a public walkway and an open-air glass gallery.', 'open', 'https://www.museumofglass.org/bridge-of-glass', 'America/Los_Angeles'),
  ('Gospodor Monument Park', 'gospodor-monument-park', 'roadside-oddities', 46.45636, -122.88469, 'Toledo', 'WA', 'Tall steel towers and monumental figures rise beside Interstate 5 in a private roadside memorial complex created by Dominic Gospodor. The safest experience is from designated lawful roadside or viewing areas; do not enter private property.', 'roadside', 'https://www.roadsideamerica.com/story/2048', 'America/Los_Angeles'),
  ('Toppenish Murals', 'toppenish-murals', 'roadside-oddities', 46.37582, -120.31114, 'Toppenish', 'WA', 'Dozens of large murals across downtown depict regional history, railroads, ranching, and community life. The entire historic district functions as a dispersed outdoor gallery rather than a single attraction.', 'open', 'https://www.visittoppenish.com/', 'America/Los_Angeles'),
  ('Twin Sisters Rock', 'twin-sisters-rock', 'folklore', 46.0426, -118.9404, 'Wallula', 'WA', 'Two basalt pillars rise above the Columbia River landscape and are associated with Indigenous stories recorded in multiple versions. Use the established trail and respect adjacent private land and cultural significance.', 'limited', 'https://www.wta.org/go-hiking/hikes/twin-sisters-rock', 'America/Los_Angeles'),
  ('Museum of Un-Natural History', 'museum-of-un-natural-history', 'museums', 46.06684, -118.33981, 'Walla Walla', 'WA', 'A deliberately eccentric museum mixes artist-created pseudo-artifacts, strange objects, satire, and local curiosities into a tiny cabinet of un-natural history. Its limited weekly hours make checking ahead essential.', 'limited', 'https://wallawalla.org/things-to-do/museums-history/museum-of-un-natural-history/', 'America/Los_Angeles'),
  ('Whitman Mission National Historic Site', 'whitman-mission-national-historic-site', 'weird-history', 46.0427, -118.465, 'Walla Walla', 'WA', 'The site interprets the Whitman mission, the 1847 killings there, and the broader conflict and cultural disruption surrounding settlement in the region. It is a serious historic landscape rather than a paranormal attraction.', 'open', 'https://www.nps.gov/whmi/', 'America/Los_Angeles'),
  ('Grays Harbor Lighthouse', 'grays-harbor-lighthouse', 'weird-history', 46.88822, -124.11691, 'Westport', 'WA', 'Washington''s tallest lighthouse rises inland from today''s shoreline because the coast has shifted outward since it was built. Climbing access is seasonal and scheduled, while the exterior remains the landmark.', 'limited', 'https://www.westportmaritimemuseum.com/grays-harbor-lighthouse/', 'America/Los_Angeles'),
  ('Christian Worship Center — ''Church of God-Zillah''', 'christian-worship-center-church-of-god-zillah', 'roadside-oddities', 46.3977, -120.2495, 'Zillah', 'WA', 'The congregation''s historic use of the phrase ''Church of God-Zillah'' turned an ordinary denominational name into a famous Godzilla pun. It is an active church and school, so the stop is for lawful exterior viewing unless attending or invited.', 'roadside', 'https://cwczillah.org/vision.html', 'America/Los_Angeles'),
  ('Teapot Dome Service Station', 'teapot-dome-service-station', 'roadside-oddities', 46.40472, -120.26942, 'Zillah', 'WA', 'A tiny gas-station building shaped like a teapot was built in the 1920s as a visual joke about the Teapot Dome political scandal. The preserved structure is one of Washington''s best examples of literal novelty architecture.', 'open', 'https://www.cityofzillah.us/', 'America/Los_Angeles'),
  ('Wellington Ghost Town', 'wellington-ghost-town', 'weird-history', 47.7472, -121.1271, 'Stevens Pass', 'WA', 'Forest trails lead to remnants of Wellington, the railroad settlement devastated by the 1910 avalanche that killed 96 people. Snow, road conditions, and deteriorated railroad structures make this a seasonal historic hike, not an abandoned-building exploration.', 'limited', 'https://www.wta.org/go-hiking/hikes/wellington-ghost-town', 'America/Los_Angeles'),
  ('Melmont Ghost Town', 'melmont-ghost-town', 'weird-history', 47.0805, -122.0478, 'Carbonado', 'WA', 'Ruins, foundations, and traces of a former coal-mining settlement survive along a forest trail beside the Carbon River. Access can be affected by bridge and road conditions, so check the current route before going.', 'limited', 'https://www.wta.org/go-hiking/hikes/melmont-ghost-town', 'America/Los_Angeles'),
  ('Monte Cristo Ghost Town', 'monte-cristo-ghost-town', 'weird-history', 48.027, -121.4447, 'Granite Falls', 'WA', 'A long trail reaches the remains of an isolated Cascade mining town where weather, floods, and economics defeated ambitious development. The trip is a substantial seasonal hike rather than a drive-up abandoned town.', 'limited', 'https://www.wta.org/go-hiking/hikes/monte-cristo-143', 'America/Los_Angeles'),
  ('Fort Worden Artillery Batteries', 'fort-worden-artillery-batteries', 'weird-history', 48.13444, -122.76691, 'Port Townsend', 'WA', 'Concrete coastal gun batteries from the Endicott-era defense system spread across the bluffs above Puget Sound. Many exterior passages are publicly accessible, but visitors should obey barriers and avoid closed or unsafe spaces.', 'open', 'https://parks.wa.gov/find-parks/state-parks/fort-worden-historical-state-park', 'America/Los_Angeles'),
  ('Fort Casey Artillery Batteries', 'fort-casey-artillery-batteries', 'weird-history', 48.16155, -122.67767, 'Coupeville', 'WA', 'Massive concrete gun emplacements and disappearing-gun mechanisms survive above Admiralty Inlet. The fort''s empty chambers and exposed machinery create a particularly atmospheric piece of coastal military history.', 'open', 'https://parks.wa.gov/find-parks/state-parks/fort-casey-historical-state-park', 'America/Los_Angeles'),
  ('Fort Flagler Artillery Batteries', 'fort-flagler-artillery-batteries', 'weird-history', 48.08584, -122.70164, 'Nordland', 'WA', 'Former coastal-defense batteries, bunkers, and military buildings occupy the northern end of Marrowstone Island. Public park access makes this one of the safer ways to experience Washington''s abandoned-looking fortifications.', 'open', 'https://parks.wa.gov/find-parks/state-parks/fort-flagler-historical-state-park', 'America/Los_Angeles'),
  ('Tokeland Hotel', 'tokeland-hotel', 'haunted', 46.70836, -123.98454, 'Tokeland', 'WA', 'Washington''s oldest hotel still operates near Willapa Bay and has accumulated long-running stories of unusual noises and reported hauntings. Treat those stories as lore and visit as a legitimate hotel or restaurant guest rather than as an unauthorized ghost hunt.', 'limited', 'https://www.tokelandhotel.com/', 'America/Los_Angeles'),
  ('Fort Columbia Historical State Park', 'fort-columbia-historical-state-park', 'weird-history', 46.2604, -123.9186, 'Chinook', 'WA', 'Gun batteries, bunkers, and historic buildings from a former Columbia River coastal-defense installation remain spread across a wooded hillside. Public state-park access provides a legal way to explore the fort''s military landscape.', 'open', 'https://parks.wa.gov/find-parks/state-parks/fort-columbia-historical-state-park', 'America/Los_Angeles'),
  ('Garbage Goat', 'garbage-goat', 'roadside-oddities', 47.66069, -117.4209, 'Spokane', 'WA', 'A steel goat created for Expo ''74 uses a vacuum system to suck up small pieces of trash offered by visitors. The bizarrely functional sculpture has become one of Riverfront Park''s most beloved oddities.', 'open', 'https://my.spokanecity.org/riverfrontspokane/sightseeing/', 'America/Los_Angeles'),
  ('Childhood Express — Big Red Wagon', 'childhood-express-big-red-wagon', 'roadside-oddities', 47.66018, -117.42166, 'Spokane', 'WA', 'This enormous red Radio Flyer-style wagon is a climbable public sculpture whose handle doubles as a slide. Its deliberately oversized scale turns a familiar childhood toy into part of the Riverfront Park landscape.', 'open', 'https://www.visitspokane.com/riverfront-park-map/', 'America/Los_Angeles'),
  ('Garland Milk Bottle', 'garland-milk-bottle', 'roadside-oddities', 47.69317, -117.42532, 'Spokane', 'WA', 'A 1935 restaurant building is shaped like a giant milk bottle, preserving the era when businesses literally turned their products into architecture. The landmark still functions as a restaurant in the Garland District.', 'open', 'https://www.visitspokane.com/directory/the-milk-bottle/', 'America/Los_Angeles'),
  ('Benewah Milk Bottle — Cedar Street', 'benewah-milk-bottle-cedar-street', 'roadside-oddities', 47.65242, -117.4323, 'Spokane', 'WA', 'A second 1930s Benewah Dairy building uses the same giant milk-bottle form on Cedar Street. It survives as a National Register-listed example of literal advertising architecture; view respectfully from lawful public areas.', 'roadside', 'https://properties.historicspokane.org/property/?PropertyID=1728', 'America/Los_Angeles')
on conflict (slug) do update set
  name          = excluded.name,
  category      = excluded.category,
  city          = excluded.city,
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  timezone      = excluded.timezone;
